// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// An agent's daily limit (UTC day) and today's spend.
	// (GET /agents/{agentId}/budget)
	GetAgentBudget(ctx context.Context, request GetAgentBudgetRequestObject) (GetAgentBudgetResponseObject, error)
	// Set an agent's daily limit. A template's spendUSD is only the default for a new agent.
	// (PUT /agents/{agentId}/budget)
	SetAgentBudget(ctx context.Context, request SetAgentBudgetRequestObject) (SetAgentBudgetResponseObject, error)
	// The servers an agent may use.
	// (GET /agents/{agentId}/mcp-servers)
	GetAgentMcpServers(ctx context.Context, request GetAgentMcpServersRequestObject) (GetAgentMcpServersResponseObject, error)
	// Replace the servers an agent may use, each optionally narrowed to some tools. Tools are
	// offered by tier; a tool the server adds later enters the ask tier for an agent that allows the
	// whole server.
	// (PUT /agents/{agentId}/mcp-servers)
	SetAgentMcpServers(ctx context.Context, request SetAgentMcpServersRequestObject) (SetAgentMcpServersResponseObject, error)
	// Read the org's audit log, newest first.
	// (GET /audit)
	ListAuditEvents(ctx context.Context, request ListAuditEventsRequestObject) (ListAuditEventsResponseObject, error)
	// The org's monthly cap (calendar month, UTC), its platform ceiling and this month's spend.
	// (GET /budget)
	GetBudget(ctx context.Context, request GetBudgetRequestObject) (GetBudgetResponseObject, error)
	// Set the org's monthly cap, or clear it by leaving `monthlyCapUsd` out.
	// (PUT /budget)
	SetBudget(ctx context.Context, request SetBudgetRequestObject) (SetBudgetResponseObject, error)
	// List the org's remote MCP servers, entered and declared, with their health.
	// (GET /mcp-servers)
	ListMcpServers(ctx context.Context, request ListMcpServersRequestObject) (ListMcpServersResponseObject, error)
	// Add a remote MCP server. A server that asks each user to sign in with OAuth is refused (planned
	// for v0.2).
	// (POST /mcp-servers)
	CreateMcpServer(ctx context.Context, request CreateMcpServerRequestObject) (CreateMcpServerResponseObject, error)
	// Delete a server, its tools and the agents' allowances of it. Declared servers answer 409.
	// (DELETE /mcp-servers/{serverId})
	DeleteMcpServer(ctx context.Context, request DeleteMcpServerRequestObject) (DeleteMcpServerResponseObject, error)
	// Get a server.
	// (GET /mcp-servers/{serverId})
	GetMcpServer(ctx context.Context, request GetMcpServerRequestObject) (GetMcpServerResponseObject, error)
	// Change a server's URL, transport or credential. Declared servers answer 409.
	// (PATCH /mcp-servers/{serverId})
	UpdateMcpServer(ctx context.Context, request UpdateMcpServerRequestObject) (UpdateMcpServerResponseObject, error)
	// The server's tools with their tiers and review flags.
	// (GET /mcp-servers/{serverId}/tools)
	ListMcpTools(ctx context.Context, request ListMcpToolsRequestObject) (ListMcpToolsResponseObject, error)
	// Mark a changed tool as reviewed without changing its tier.
	// (POST /mcp-servers/{serverId}/tools/{toolName}/review)
	AcknowledgeMcpToolReview(ctx context.Context, request AcknowledgeMcpToolReviewRequestObject) (AcknowledgeMcpToolReviewResponseObject, error)
	// Move a tool to a tier: `ask` (a human approves each call), `auto` (the agent calls it) or
	// `never`. Works on declared servers too. Clears the tool's review flag.
	// (PUT /mcp-servers/{serverId}/tools/{toolName}/tier)
	SetMcpToolTier(ctx context.Context, request SetMcpToolTierRequestObject) (SetMcpToolTierResponseObject, error)
	// Require two approvers for calls to a tool in the ask tier: distinct admins or owners, neither the
	// ticket's creator. Off by default.
	// (PUT /mcp-servers/{serverId}/tools/{toolName}/two-approvers)
	SetMcpToolTwoApprovers(ctx context.Context, request SetMcpToolTwoApproversRequestObject) (SetMcpToolTwoApproversResponseObject, error)
	// List the org's models, entered and declared.
	// (GET /models)
	ListModels(ctx context.Context, request ListModelsRequestObject) (ListModelsResponseObject, error)
	// Add a model to a provider. Its price is an org price or a default one.
	// (POST /models)
	CreateModel(ctx context.Context, request CreateModelRequestObject) (CreateModelResponseObject, error)
	// Delete a model. Declared models answer 409.
	// (DELETE /models/{modelId})
	DeleteModel(ctx context.Context, request DeleteModelRequestObject) (DeleteModelResponseObject, error)
	// Get a model.
	// (GET /models/{modelId})
	GetModel(ctx context.Context, request GetModelRequestObject) (GetModelResponseObject, error)
	// Change a model's routing guard. Declared models answer 409.
	// (PATCH /models/{modelId})
	UpdateModel(ctx context.Context, request UpdateModelRequestObject) (UpdateModelResponseObject, error)
	// List the org's own prices, every version, newest first per name.
	// (GET /prices)
	ListPrices(ctx context.Context, request ListPricesRequestObject) (ListPricesResponseObject, error)
	// Add a version of a named price. Earlier versions never change.
	// (POST /prices)
	SetPrice(ctx context.Context, request SetPriceRequestObject) (SetPriceResponseObject, error)
	// The default price list this installation runs and the versions before it.
	// (GET /prices/defaults)
	GetDefaultPrices(ctx context.Context, request GetDefaultPricesRequestObject) (GetDefaultPricesResponseObject, error)
	// What changed in the default price list between two versions (after an upgrade).
	// (GET /prices/defaults/changes)
	GetDefaultPriceChanges(ctx context.Context, request GetDefaultPriceChangesRequestObject) (GetDefaultPriceChangesResponseObject, error)
	// Price entries whose recomputed cost differs from the gateway's by more than 1%.
	// (GET /prices/flagged)
	ListFlaggedPrices(ctx context.Context, request ListFlaggedPricesRequestObject) (ListFlaggedPricesResponseObject, error)
	// End a named price now. Its versions stay for the ledger entries that cite them.
	// (DELETE /prices/{name})
	RetirePrice(ctx context.Context, request RetirePriceRequestObject) (RetirePriceResponseObject, error)
	// List the org's providers, entered and declared.
	// (GET /providers)
	ListProviders(ctx context.Context, request ListProvidersRequestObject) (ListProvidersResponseObject, error)
	// Add a provider.
	// (POST /providers)
	CreateProvider(ctx context.Context, request CreateProviderRequestObject) (CreateProviderResponseObject, error)
	// Delete a provider and its models. Declared providers answer 409.
	// (DELETE /providers/{providerId})
	DeleteProvider(ctx context.Context, request DeleteProviderRequestObject) (DeleteProviderResponseObject, error)
	// Get a provider.
	// (GET /providers/{providerId})
	GetProvider(ctx context.Context, request GetProviderRequestObject) (GetProviderResponseObject, error)
	// Change a provider's type, URL or key. Declared providers answer 409.
	// (PATCH /providers/{providerId})
	UpdateProvider(ctx context.Context, request UpdateProviderRequestObject) (UpdateProviderResponseObject, error)
	// Spend per model, with estimated usage shown apart from reported usage.
	// (GET /spend)
	GetSpendReport(ctx context.Context, request GetSpendReportRequestObject) (GetSpendReportResponseObject, error)
	// List the org's API tokens, newest first.
	// (GET /tokens)
	ListTokens(ctx context.Context, request ListTokensRequestObject) (ListTokensResponseObject, error)
	// Create an API token. The secret is shown once.
	// (POST /tokens)
	CreateToken(ctx context.Context, request CreateTokenRequestObject) (CreateTokenResponseObject, error)
	// Revoke a token. Revoking twice is fine.
	// (DELETE /tokens/{tokenId})
	RevokeToken(ctx context.Context, request RevokeTokenRequestObject) (RevokeTokenResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

